// Xattrkey4Iter iterates over variable-size Xattrkey4 entries.
type Xattrkey4Iter struct {
	b      []byte
	count  int
	i      int
	curLen int
}

func (it *Xattrkey4Iter) Next() bool {
	b := it.b
	if it.curLen > 0 {
		if len(b) < it.curLen {
			return false
		}
		b = b[it.curLen:]
		it.curLen = 0
	}
	if it.i >= it.count {
		it.b = b
		return false
	}
	if len(b) < 4 {
		return false
	}
	n := int(binary.BigEndian.Uint32(b[0:4]))
	padded := (n + 3) &^ 3
	total := 4 + padded
	if len(b) < total {
		return false
	}
	it.b = b
	it.curLen = total
	it.i++
	return true
}

func (it *Xattrkey4Iter) LxrName() Xattrkey4 {
	return Xattrkey4(it.b)
}

