// -------------------------------------------------------

func NfsFtype4Name(v uint32) string {
	switch v {
	case NF4REG:
		return "NF4REG"
	case NF4DIR:
		return "NF4DIR"
	case NF4BLK:
		return "NF4BLK"
	case NF4CHR:
		return "NF4CHR"
	case NF4LNK:
		return "NF4LNK"
	case NF4SOCK:
		return "NF4SOCK"
	case NF4FIFO:
		return "NF4FIFO"
	case NF4ATTRDIR:
		return "NF4ATTRDIR"
	case NF4NAMEDATTR:
		return "NF4NAMEDATTR"
	default:
		return fmt.Sprintf("nfs_ftype4(%v)", v)
	}
}

